// ============================================================
//  painted — Phase 8: real paintings for area cards, death and ending screens, logbook sketches.
//
//  js/painted-manifest.js (generated by tools/art/manifest.py) lists which JPGs exist under
//  img/painted/<group>/<key>.jpg. A picture is used only when it is in the manifest, the switch is on
//  and it has actually loaded and decoded; otherwise the procedural stand-ins in screens.js and
//  logmap.js draw as before. Nothing here ever blocks boot, map loading or a screen: callers ask
//  PAINTED.ready() synchronously and use the stand-in for that visit when the answer is no.
//
//  Memory: at most MAX_DECODED large images are held (least recently used goes first). Warm-ups
//  (death pictures) only fetch into the HTTP cache and keep nothing.
// ============================================================
'use strict';

if (typeof GFX !== 'undefined' && GFX.paintedArt === undefined) GFX.paintedArt = true;

const PAINTED = (function () {
  const KEY = 'octave.painted.v1', MAX_DECODED = 8;
  const GROUPS = ['area', 'death', 'ending', 'sketch'];
  const FAMILIES = ['street', 'hall', 'hearth', 'mill', 'chapel', 'workshop', 'hedge', 'quarry', 'root', 'grove', 'woods', 'crypt', 'belfry', 'arena'];
  const DEATHS = ['heartglass', 'unwrite', 'greening', 'fall', 'drown', 'trap', 'bolt', 'grapnel', 'beast', 'soldier', 'golem', 'wearer', 'quiet', 'found'];

  let manifest = (typeof PAINTED_MANIFEST === 'object' && PAINTED_MANIFEST) ? PAINTED_MANIFEST : {};
  const overrides = {};          // test hook: "group/key" -> url
  const lru = new Map();         // "group/key" -> Image (decoded, ready)
  const pending = new Map();     // "group/key" -> Promise
  const failed = new Set();      // "group/key" that errored this session

  const id = (g, k) => g + '/' + k;
  const safe = (s) => typeof s === 'string' && /^[a-z0-9_]+$/.test(s);
  const own = (o, k) => Object.prototype.hasOwnProperty.call(o, k);

  function enabled() { return typeof GFX === 'undefined' || GFX.paintedArt !== false; }
  function save() { try { localStorage.setItem(KEY, JSON.stringify({ on: enabled() })); } catch (e) { /* no storage: fine */ } }
  function loadPref() {
    try { const o = JSON.parse(localStorage.getItem(KEY) || 'null'); if (o && typeof GFX !== 'undefined' && o.on === false) GFX.paintedArt = false; } catch (e) { /* default on */ }
  }

  // Is there a painting for this picture (manifest says so, switch on, no load failure)?
  function has(group, key) {
    if (!enabled() || !safe(group) || !safe(key)) return false;
    const i = id(group, key);
    return !failed.has(i) && (own(overrides, i) || own(manifest, i));
  }
  function url(group, key) {
    if (!safe(group) || !safe(key)) return null;
    const i = id(group, key);
    return own(overrides, i) ? overrides[i] : 'img/painted/' + group + '/' + key + '.jpg';
  }

  function touch(i, im) { lru.delete(i); lru.set(i, im); while (lru.size > MAX_DECODED) lru.delete(lru.keys().next().value); }

  // Fetch and decode; resolves to the Image or null. Never rejects.
  function load(group, key) {
    if (!has(group, key)) return Promise.resolve(null);
    const i = id(group, key);
    if (lru.has(i)) { touch(i, lru.get(i)); return Promise.resolve(lru.get(i)); }
    if (pending.has(i)) return pending.get(i);
    const p = new Promise((resolve) => {
      const im = new Image();
      im.onload = () => {
        const done = () => { pending.delete(i); touch(i, im); resolve(im); };
        if (im.decode) im.decode().then(done, done); else done();
      };
      // a missing or corrupt file: remember it so the stand-in is used from now on, no broken image
      im.onerror = () => { pending.delete(i); failed.add(i); resolve(null); };
      im.src = url(group, key);
    });
    pending.set(i, p);
    return p;
  }
  // Synchronous: the decoded Image if it is ready right now, else null (caller uses the stand-in).
  function ready(group, key) {
    if (!has(group, key)) return null;
    const i = id(group, key), im = lru.get(i);
    if (!im) { load(group, key); return null; } // start fetching for next time
    touch(i, im);
    return im;
  }
  // Only fetches into the HTTP cache; holds nothing.
  function warm(group, key) {
    if (!has(group, key)) return;
    const i = id(group, key);
    if (lru.has(i) || pending.has(i)) return;
    const im = new Image(); im.onerror = () => failed.add(i); im.src = url(group, key);
  }

  // Cover-fit draw (centre-cropped) of a loaded image into a w x h canvas context.
  function drawCover(x, im, w, h) {
    const iw = im.naturalWidth || im.width, ih = im.naturalHeight || im.height;
    const s = Math.max(w / iw, h / ih), dw = iw * s, dh = ih * s;
    x.imageSmoothingEnabled = true; x.imageSmoothingQuality = 'high';
    x.drawImage(im, (w - dw) / 2, (h - dh) / 2, dw, dh);
  }

  // ---- preloading: after boot, in idle time, never blocking
  function neighbours(mapId) {
    const out = new Set();
    try {
      const m = G.maps[mapId];
      const add = (p) => { if (p && typeof p.map === 'string') out.add(p.map); };
      for (const c of (m.cells || [])) if (c && c.portal) add(c.portal);
      for (const e of (m.entities || [])) if (e && e.portal) add(e.portal);
    } catch (e) { /* none */ }
    return [...out];
  }
  function familyOf(mapId) { try { return SCREENS.familyFor(mapId); } catch (e) { return null; } }
  function preloadArea(mapId) {
    const fams = new Set([familyOf(mapId)]);
    for (const n of neighbours(mapId)) fams.add(familyOf(n));
    for (const f of fams) if (f && has('area', f) && !lru.has(id('area', f))) load('area', f);
  }
  let warmed = false;
  function warmDeaths() {
    if (warmed) return; warmed = true;
    const idle = window.requestIdleCallback ? (f) => window.requestIdleCallback(f, { timeout: 4000 }) : (f) => setTimeout(f, 800);
    let n = 0;
    const next = () => { if (n >= DEATHS.length + 8) return; if (n < DEATHS.length) warm('death', DEATHS[n]); n++; idle(next); };
    idle(next);
  }
  function boot() {
    try { if (typeof G !== 'undefined' && G.mapId) preloadArea(G.mapId); } catch (e) { /* none */ }
    setTimeout(warmDeaths, 2500);
  }

  // ---- Options row (appended to Graphics & access, like fp-feel.js)
  function appendRow() {
    const grid = document.querySelector('#modal-panel .ctl-grid');
    if (!grid || document.getElementById('painted-head')) return;
    const mk = (tag, props, text) => { const e = document.createElement(tag); for (const k in props) e.setAttribute(k, props[k]); if (text != null) e.textContent = text; return e; };
    const label = mk('span', { class: 'gfx-label', id: 'painted-head' }, 'Painted art ');
    label.appendChild(mk('small', { class: 'muted' }, 'paintings on area cards, death and ending screens and logbook sketches; Stand-ins uses the drawn pictures'));
    const b = mk('button', { class: 'dfbtn small', id: 'painted-toggle', type: 'button', 'aria-label': 'Painted art' }, '');
    const sync = () => { const on = enabled(); b.textContent = on ? 'On' : 'Stand-ins'; b.setAttribute('aria-pressed', on ? 'true' : 'false'); b.classList.toggle('sel', on); };
    b.onclick = () => { GFX.paintedArt = !enabled(); save(); sync(); };
    grid.appendChild(label); grid.appendChild(b); sync();
  }
  function wire() {
    if (typeof renderAccessibilityMenu === 'function') {
      const _acc = renderAccessibilityMenu;
      renderAccessibilityMenu = function () {
        const r = _acc.apply(this, arguments);
        try { appendRow(); } catch (e) { console.warn('painted: options row failed', e); }
        return r;
      };
    }
    if (typeof loadMap === 'function') {
      const _lm = loadMap;
      loadMap = function (mid) {
        const r = _lm.apply(this, arguments);
        try { if (manifestSize()) setTimeout(() => preloadArea(mid), 0); } catch (e) { /* none */ }
        return r;
      };
    }
    if (typeof window !== 'undefined') {
      if (document.readyState === 'complete') setTimeout(boot, 0); else window.addEventListener('load', () => setTimeout(boot, 0));
    }
  }
  const manifestSize = () => Object.keys(manifest).length + Object.keys(overrides).length;

  // Test hooks: replace the manifest / point a picture at a data or blob URL; reset restores the real state.
  const test = {
    setManifest(m) { manifest = m || {}; },
    setUrl(group, key, u) { overrides[id(group, key)] = u; },
    reset() { manifest = (typeof PAINTED_MANIFEST === 'object' && PAINTED_MANIFEST) || {}; for (const k of Object.keys(overrides)) delete overrides[k]; lru.clear(); pending.clear(); failed.clear(); },
    decoded() { return lru.size; },
    failed() { return [...failed]; },
  };

  loadPref();
  try { wire(); } catch (e) { console.warn('painted: not installed', e); }
  return { has, url, load, ready, warm, drawCover, preloadArea, enabled, save, appendRow, GROUPS, FAMILIES, DEATHS, MAX_DECODED, test };
})();
